import{describe,it,expect}from"vitest";import{BIODIVERSITY_HOTSPOTS_DATA,validateBiodiversityData,getHotspotById,calculateHotspotPriorityScore}from"../../frontend/biodiversity-hotspots/script.js";describe("Biodiversity Hotspots Dataset Integrity (#579)",()=>{it("covers all 4 globally recognized hotspots in India",()=>{expect(Array.isArray(BIODIVERSITY_HOTSPOTS_DATA)).toBe(!0),expect(BIODIVERSITY_HOTSPOTS_DATA.length).toBe(4)}),it("validates dataset field completeness",()=>{const t=validateBiodiversityData(BIODIVERSITY_HOTSPOTS_DATA);expect(t.isValid).toBe(!0),expect(t.errors).toEqual([])}),it("contains the four expected hotspot IDs",()=>{const t=BIODIVERSITY_HOTSPOTS_DATA.map(t=>t.id);expect(t).toContain("himalaya"),expect(t).toContain("western-ghats"),expect(t).toContain("indo-burma"),expect(t).toContain("sundaland-nicobar")}),it("ensures every hotspot has endemic species, threats, and criteria",()=>{BIODIVERSITY_HOTSPOTS_DATA.forEach(t=>{expect(t).toHaveProperty("name"),expect(t).toHaveProperty("statesCovered"),expect(t.ecologicalCriteria).toHaveProperty("endemicPlants"),expect(t.ecologicalCriteria).toHaveProperty("habitatLossPercent"),expect(Array.isArray(t.keyFloraFauna)).toBe(!0),expect(t.keyFloraFauna.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(t.threats)).toBe(!0),expect(t.threats.length).toBeGreaterThan(0)})})}),describe("Hotspot Helper & Calculation Math",()=>{it("retrieves hotspot by valid ID",()=>{const t=getHotspotById("western-ghats");expect(t.name).toContain("Western Ghats"),expect(t.statesCovered).toContain("Kerala")}),it("defaults to first hotspot if invalid ID provided",()=>{const t=getHotspotById("unknown");expect(t.id).toBe("himalaya")}),it("calculates ecological priority score correctly",()=>{const t=calculateHotspotPriorityScore(75,3160);expect(t).toBeGreaterThan(50),expect(t).toBeLessThanOrEqual(100)})});